/* قاعدةُ تطبيعٍ **واحدة** لكلّ بحثٍ في التطبيق: من كتب «أرامكو» بهمزةٍ
   ومن كتبها بألفٍ يجد الشيءَ نفسه. وتُصدَّر كي لا تُنسَخ نسخةٌ ثانيةٌ
   في شاشةٍ أخرى فتفترق القاعدتان بصمت. */
export const norm = (s: string) => (s || "").toLowerCase().replace(/[أإآ]/g, "ا").trim();

export function searchCompanies(q: string, limit = 8): SaudiCompany[] {
  const n = norm(q);
  if (!n) return [];
  /* الاسم الدارج يبحث كما يبحث الاسم النظامي: من كتب «معادن» كان لا يجد
     شيئاً لأن اسمها المسجَّل «التعدين العربية السعودية» — و٤١ شركةً أخرى
     مثلها. الجدول مولَّد من دليل السوق في الخادم، والعرض يبقى نظامياً. */
  const hits = SAUDI_COMPANIES.filter(c =>
    c.symbol.startsWith(n) ||
    norm(c.name_ar).includes(n) ||
    c.name_en.toLowerCase().includes(n) ||
    norm(COMPANY_ALIASES[c.symbol] || "").includes(n)
  ).slice(0, limit);
  /* ══ رمزٌ خارج الدليل يبقى قابلاً للفتح ══ (بأمر المالك)
     بحث المالك عن «صناديق البلاد للذهب والأسهم الأمريكية والتقنية» فلم
     يجدها: الدليلُ شركاتُ السوق (٣٩٦) ولا يحوي **صناديق المؤشرات
     المتداولة** أصلاً — والنقصُ عامٌّ في الصناديق كلّها لا في هذه الثلاثة.
     ولا تُضاف رموزُها بالتخمين: رمزٌ مختلَق يجلب سعرَ ورقةٍ أخرى إلى
     محفظة المالك، وذلك أسوأ من غيابه.
     فمن كتب رمزاً رباعياً لا يعرفه الدليل يجده صفّاً صريحاً يقول إنه خارج
     الدليل — يفتحه ويقرأ سعره من المصدر، ولا يُترك أمام فراغٍ صامت. */
  if (!hits.length && /^\d{4}$/.test(n)) {
    return [{ symbol: n, name_ar: `الرمز ${n}`, name_en: "",
              sector: "خارج الدليل" }];
  }
  return hits;
}

export function lookupCompany(symbol: string): SaudiCompany | undefined {
  return SAUDI_COMPANIES.find(c => c.symbol === (symbol || "").trim());
}

/** القطاعات المعتمدة (٢٢) مشتقّة من الدليل نفسه — مصدر حقيقة واحد لقوائم
 *  الاختيار في كل الواجهة، فلا تعتمد على بيانات قد تكون فارغة (كصفوف الفرز
 *  قبل حسابها) ولا تُكتب يدوياً فتنحرف عن الدليل. */
export const SECTORS: string[] = Array.from(
  new Set(SAUDI_COMPANIES.map(c => c.sector).filter(Boolean))
).sort((a, b) => a.localeCompare(b, "ar"));
